How do you write a JavaScript function that calculates the area of a triangle given the lengths of its sides? 
// Calculate the area of a triangle
function getArea(a, b, c) {
    let s = (a + b + c) / 2;
    return Math.sqrt(s * (s - a) * (s - b) * (s - c));
}
// Example usage:
